/**
 * Builds public/_redirects from docs/site-audit/redirect-map.csv.
 *
 * The header of _redirects has claimed since Prompt 09 that it is generated by
 * this file. It was not - the file did not exist, and the CSV and the rules had
 * to be kept in step by hand across 763 lines. That is a trap for exactly the
 * kind of change the 1.1.0 release makes, so the generator is now real.
 *
 * Ordering is not cosmetic. Cloudflare evaluates static rules before dynamic
 * ones and, within a group, the first match wins - so every specific poem rule
 * must be emitted above the /living-workshop/* catch-all or every post lands on
 * the fallback instead of on its own poem.
 *
 *   node tools/generate-redirects.mjs           # write public/_redirects
 *   node tools/generate-redirects.mjs --check   # fail if it is out of date
 */
import { readFileSync, writeFileSync } from 'node:fs';

const CSV = 'docs/site-audit/redirect-map.csv';
const OUT = 'public/_redirects';

/** Minimal RFC-4180 reader: the map has quoted fields containing commas. */
function parseCsv(text) {
  const rows = [];
  let row = [], field = '', quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else quoted = false; }
      else field += c;
    } else if (c === '"') quoted = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (c !== '\r') field += c;
  }
  if (field || row.length) { row.push(field); rows.push(row); }
  const head = rows.shift();
  return rows.filter(r => r.length === head.length && r[0])
             .map(r => Object.fromEntries(head.map((h, i) => [h, r[i]])));
}

const rows = parseCsv(readFileSync(CSV, 'utf8'));

// A page kept at its own path must not have a rule: it would redirect to itself.
const live = rows.filter(r => r.disposition !== 'retained - same path on the new site');

const isArchivePoem = r =>
  r.legacy_url.startsWith('/living-workshop/') &&
  r.intended_destination.startsWith('https://brianspoems.com');

// Anything still pointed at the generic fallback is covered by the catch-all
// below, so emitting it individually would only burn one of the 2,000 static
// rule slots.
const FALLBACK = '/poems';
// "/living-workshop/*" does not match the bare "/living-workshop", so the
// landing page keeps an explicit rule of its own.
const isFallback = r =>
  r.legacy_url.startsWith('/living-workshop/') && r.intended_destination === FALLBACK;

const byUrl = (a, b) => a.legacy_url < b.legacy_url ? -1 : a.legacy_url > b.legacy_url ? 1 : 0;
const poems = live.filter(isArchivePoem).sort(byUrl);
const pages = live.filter(r => !isArchivePoem(r) && !isFallback(r) && !r.legacy_url.includes('*')).sort(byUrl);

const rule = r => `${r.legacy_url}  ${r.intended_destination}  301`;

const out = `# Legacy URL redirects for the brianmueller.com replatform.
#
# GENERATED - do not hand-edit. Source of truth is
# docs/site-audit/redirect-map.csv; regenerate with tools/generate-redirects.mjs.
#
# Cloudflare evaluates STATIC rules before dynamic ones and, within a group,
# the top-most match wins. The specific poem redirects below must therefore
# stay above the /living-workshop/* catch-all, or every post would land on
# ${FALLBACK} instead of on its own poem.
#
# Limits: 2,000 static + 100 dynamic. This file uses ${poems.length + pages.length} static and 5 dynamic.
#
# NOT redirected, on purpose: /privacy-policy, /cookies-policy, /disclaimer
# and /terms-conditions keep their old paths on the new site. A rule for any
# of them would be a redirect loop.

# ---- pages, stores and archives -------------------------------------------
${pages.map(rule).join('\n')}

# ---- individual poems, matched by comparing the archived post text with the
#      poem at each candidate permalink on brianspoems.com. Slug matching
#      alone gets some of these wrong: /living-workshop/in-the-mirror belongs
#      to /poem/in-the-mirror-2, not /poem/in-the-mirror. -------------------
${poems.map(rule).join('\n')}

# ---- dynamic catch-alls. These MUST come last. ----------------------------
# Tag and category listings have no equivalent on the new site.
/living-workshop/tag/*       ${FALLBACK}  301
/living-workshop/category/*  ${FALLBACK}  301
# Any remaining post: either no poem permalink exists for it, or the match
# was not confident enough to assert. ${FALLBACK} carries a line written for
# someone who arrived from an old link, and points at the archive.
/living-workshop/*           ${FALLBACK}  301
# Retired storefront.
/store/p/*                   /books 301
/store/*                     /books 301

`;

if (process.argv.includes('--check')) {
  const have = readFileSync(OUT, 'utf8');
  if (have !== out) {
    console.error(`generate-redirects: ${OUT} is out of date with ${CSV}. Run: node tools/generate-redirects.mjs`);
    process.exit(1);
  }
  console.log(`redirects: ${OUT} matches ${CSV} · ${poems.length + pages.length} static, 5 dynamic`);
} else {
  writeFileSync(OUT, out);
  console.log(`redirects: wrote ${OUT} · ${pages.length} page rules, ${poems.length} poem rules, 5 dynamic`);
}
